import{_ as i,o as t,c as a,l as n,t as s,N as r}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"git-merge-index | x-cmd man (git man1) | Run a merge for files needing merging","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-merge-index - Run a merge for files needing merging","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-merge-index | x-cmd man (git man1) | Run a merge for files needing merging"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-merge-index - Run a merge for files needing merging"}]]},"headers":[],"params":{"isMan":true,"man":"git-merge-index","category":"git man1","desc":"Run a merge for files needing merging"},"relativePath":"git/man1/git-merge-index.md","filePath":"git/man1/git-merge-index.md"}'),o={name:"git/man1/git-merge-index.md"},g={class:"visually-hidden"},h=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-merge-index - Run a merge for files needing merging</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-o] [-q] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">merge-program</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ( [--] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) )</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This looks up the &lt;file&gt;(s) in the index and, if there are any merge entries, passes the SHA-1 hash for those files as arguments 1, 2, 3 (empty argument if no file), and &lt;file&gt; as argument 4. File modes for the three files are passed as arguments 5, 6 and 7.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--</p><blockquote><p>Do not interpret any more arguments as options.</p></blockquote><p>-a</p><blockquote><p>Run merge against all files in the index that need merging.</p></blockquote><p>-o</p><blockquote><p>Instead of stopping at the first failed merge, do all of them in one shot - continue with merging even when previous merges returned errors, and only return the error code after all the merges.</p></blockquote><p>-q</p><blockquote><p>Do not complain about a failed merge program (a merge program failure usually indicates conflicts during the merge). This is for porcelains which might want to emit custom messages.</p></blockquote><p>If <em>git merge-index</em> is called with multiple &lt;file&gt;s (or -a) then it processes them in turn only stopping if merge returns a non-zero exit code.</p><p>Typically this is run with a script calling Git&#39;s imitation of the <em>merge</em> command from the RCS package.</p><p>A sample script called <em>git merge-one-file</em> is included in the distribution.</p><p>ALERT ALERT ALERT! The Git &quot;merge object order&quot; is different from the RCS <em>merge</em> program merge object order. In the above ordering, the original is first. But the argument order to the 3-way merge program <em>merge</em> is to have the original in the middle. Don&#39;t ask me why.</p><p>Examples:</p><blockquote><pre><code>torvalds@ppc970:~/merge-test&gt; git merge-index cat MM
This is MM from the original tree.              # original
This is modified MM in the branch A.            # merge1
This is modified MM in the branch B.            # merge2
This is modified MM in the branch B.            # current contents
</code></pre></blockquote><p>or</p><blockquote><pre><code>torvalds@ppc970:~/merge-test&gt; git merge-index cat AA MM
cat: : No such file or directory
This is added AA in the branch A.
This is added AA in the branch B.
This is added AA in the branch B.
fatal: merge program failed
</code></pre></blockquote><p>where the latter example shows how <em>git merge-index</em> will stop trying to merge once anything has returned an error (i.e., <strong>cat</strong> returned an error for the AA file, because it didn&#39;t exist in the original, and thus <em>git merge-index</em> didn&#39;t even try to merge the MM thing).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,26);function l(e,m,d,p,c,u){return t(),a("div",null,[n("h1",g,s(e.$params.man),1),h])}const b=i(o,[["render",l]]);export{f as __pageData,b as default};
